请对以下 case 进行三维加权评分。

=== case_id ===
Case-17-queue-014

=== 用户原始指令 (query.txt) ===
做个简洁的取号卡,顶部一行"您的号码 A-108",中间环形显示"前面还有23人",右上角动态电量78%,夜晚深蓝紫色渐变,右边横向排三个小模块显示温度、湿度、紫外线,点数字能跳系统设置。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做个简洁的取号卡,顶部一行\"您的号码 A-108\",中间环形显示\"前面还有23人\",右上角动态电量78%,夜晚深蓝紫色渐变,右边横向排三个小模块显示温度、湿度、紫外线,点数字能跳系统设置。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModelSchema": {
    "queue": {
      "number": {
        "type": "string",
        "description": "当前取号号码。",
        "sampleValue": "A-108"
      },
      "peopleAhead": {
        "type": "number",
        "description": "当前号码前方等待人数。",
        "sampleValue": 23
      }
    },
    "device": {
      "batteryPercentText": {
        "type": "string",
        "description": "当前设备电量百分比展示文本。",
        "sampleValue": "78%"
      }
    },
    "data": {
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比。",
            "sampleValue": 62
          },
          "uvIndex": {
            "type": "string",
            "description": "当前紫外线等级。",
            "sampleValue": "弱"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

